import React, { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
import { ArrowLeft, Plus, Minus, Check } from "lucide-react";
import { COLORS, FONT_DISPLAY } from "../constants/theme";
import { fetchProductById } from "../data/products";
import { money } from "../utils/helpers";

export default function ProductDetail({ cart, addToCart, updateQty }) {
  const { id } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [qty, setQty] = useState(1);
  const [added, setAdded] = useState(false);
  const [activeImage, setActiveImage] = useState(0);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setProduct(null);
    setActiveImage(0);
    setMounted(false);

    fetchProductById(id)
      .then((data) => {
        if (!cancelled) setProduct(data);
      })
      .catch(() => {
        if (!cancelled) setProduct(null);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [id]);

  // Trigger entrance animation once content is ready
  useEffect(() => {
    if (!loading && product) {
      const t = requestAnimationFrame(() => setMounted(true));
      return () => cancelAnimationFrame(t);
    }
  }, [loading, product]);

  // Reset crossfade whenever the active image changes
  useEffect(() => {
    setImageLoaded(false);
  }, [activeImage]);

  if (loading) {
    return (
      <section style={{ padding: "100px 22px", textAlign: "center" }}>
        <p style={{ fontSize: 14, color: COLORS.textMuted }}>Loading…</p>
      </section>
    );
  }

  if (!product) {
    return (
      <section style={{ padding: "100px 22px", textAlign: "center" }}>
        <p style={{ fontFamily: FONT_DISPLAY, fontSize: 22, marginBottom: 16, color: COLORS.text }}>
          We couldn't find that piece.
        </p>
        <Link to="/" style={{ color: COLORS.verdigris, fontSize: 14 }}>
          Back to shop
        </Link>
      </section>
    );
  }

  const images = product.imageUrl && product.imageUrl.length > 0 ? product.imageUrl : [];

  // Live quantity already in the shared cart for this product — keeps this
  // page in sync with the cart drawer and the shop grid.
  const inCartQty = cart.find((item) => item.id === product.id)?.qty || 0;
  const inStock = typeof product.stockQuantity === "number" ? product.stockQuantity : Infinity;
  const outOfStock = inStock <= 0;
  const remaining = Math.max(0, inStock - inCartQty);

  const handleAdd = () => {
    const amountToAdd = Math.min(qty, remaining);
    if (amountToAdd <= 0) return;

    if (inCartQty === 0) {
      addToCart(product);
      for (let i = 1; i < amountToAdd; i++) updateQty(product.id, 1);
    } else {
      updateQty(product.id, amountToAdd);
    }

    setAdded(true);
    setTimeout(() => setAdded(false), 1600);
  };

  return (
    <section style={{ padding: "40px 22px 100px", maxWidth: 1080, margin: "0 auto" }}>
      <style>{`
        @keyframes pd-fade-up {
          from { opacity: 0; transform: translateY(14px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes pd-check-in {
          from { opacity: 0; transform: scale(0.8); }
          to { opacity: 1; transform: scale(1); }
        }
        .pd-back-link {
          transition: gap 0.25s ease, color 0.25s ease;
        }
        .pd-back-link:hover {
          gap: 10px;
          color: ${COLORS.text};
        }
        .pd-thumb {
          transition: transform 0.25s ease, border-color 0.25s ease, opacity 0.25s ease;
        }
        .pd-thumb:hover {
          transform: translateY(-3px);
        }
        .pd-qty-btn {
          transition: background 0.2s ease, transform 0.15s ease;
        }
        .pd-qty-btn:hover:not(:disabled) {
          background: ${COLORS.surfaceSoft};
        }
        .pd-qty-btn:active:not(:disabled) {
          transform: scale(0.9);
        }
        .pd-add-btn {
          transition: background 0.35s cubic-bezier(0.22, 1, 0.36, 1),
                      transform 0.2s ease,
                      box-shadow 0.35s ease;
        }
        .pd-add-btn:hover:not(:disabled) {
          transform: translateY(-2px);
          box-shadow: 0 10px 24px rgba(0, 0, 0, 0.16);
        }
        .pd-add-btn:active:not(:disabled) {
          transform: translateY(0) scale(0.98);
        }
        .pd-main-image {
          transition: opacity 0.4s ease, transform 0.6s ease;
        }
        .pd-check {
          animation: pd-check-in 0.3s cubic-bezier(0.22, 1, 0.36, 1);
        }
        .pd-in-cart-note {
          transition: opacity 0.3s ease, transform 0.3s ease;
        }
      `}</style>

      <Link
        to="/"
        className="pd-back-link"
        style={{
          display: "inline-flex",
          alignItems: "center",
          gap: 6,
          fontSize: 13,
          color: COLORS.textMuted,
          marginBottom: 32,
          textDecoration: "none",
          opacity: mounted ? 1 : 0,
          transform: mounted ? "translateY(0)" : "translateY(-6px)",
          transition: "opacity 0.5s ease, transform 0.5s ease",
        }}
      >
        <ArrowLeft size={15} />
        Back to shop
      </Link>

      <div
        className="flex flex-col md:flex-row"
        style={{ gap: 48, alignItems: "flex-start" }}
      >
        {/* Image gallery */}
        <div
          style={{
            flex: 1,
            width: "100%",
            opacity: mounted ? 1 : 0,
            transform: mounted ? "translateY(0)" : "translateY(14px)",
            transition: "opacity 0.6s ease, transform 0.6s ease",
          }}
        >
          <div
            style={{
              width: "100%",
              aspectRatio: "1 / 1",
              background: COLORS.surfaceSoft,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 20,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              position: "relative",
              overflow: "hidden",
              marginBottom: images.length > 1 ? 12 : 0,
            }}
          >
            {images.length > 0 ? (
              <img
                key={activeImage}
                src={images[activeImage]}
                alt={product.name}
                onLoad={() => setImageLoaded(true)}
                className="pd-main-image"
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  opacity: imageLoaded ? 1 : 0,
                  transform: imageLoaded ? "scale(1)" : "scale(1.03)",
                }}
              />
            ) : (
              <span style={{ fontSize: 13, color: COLORS.textFaint }}>No image available</span>
            )}
            <span
              style={{
                position: "absolute",
                top: 16,
                left: 16,
                fontSize: 11,
                letterSpacing: "0.1em",
                textTransform: "uppercase",
                color: COLORS.rust,
                background: COLORS.surfaceSoft,
                padding: "3px 8px",
                borderRadius: 4,
              }}
            >
              {product.categoryName}
            </span>
            {outOfStock && (
              <span
                style={{
                  position: "absolute",
                  top: 16,
                  right: 16,
                  fontSize: 11,
                  letterSpacing: "0.08em",
                  textTransform: "uppercase",
                  color: "#fff",
                  background: "crimson",
                  padding: "3px 9px",
                  borderRadius: 4,
                }}
              >
                Out of stock
              </span>
            )}
          </div>

          {images.length > 1 && (
            <div className="flex" style={{ gap: 10 }}>
              {images.map((src, i) => (
                <button
                  key={src + i}
                  onClick={() => setActiveImage(i)}
                  className="pd-thumb"
                  style={{
                    width: 64,
                    height: 64,
                    borderRadius: 10,
                    overflow: "hidden",
                    border: `1px solid ${i === activeImage ? COLORS.surfaceStrong : COLORS.border}`,
                    padding: 0,
                    cursor: "pointer",
                    flexShrink: 0,
                    opacity: i === activeImage ? 1 : 0.65,
                  }}
                  aria-label={`View image ${i + 1}`}
                >
                  <img
                    src={src}
                    alt={`${product.name} ${i + 1}`}
                    style={{ width: "100%", height: "100%", objectFit: "cover" }}
                  />
                </button>
              ))}
            </div>
          )}
        </div>

        <div
          style={{
            flex: 1,
            width: "100%",
            opacity: mounted ? 1 : 0,
            transform: mounted ? "translateY(0)" : "translateY(14px)",
            transition: "opacity 0.6s ease 0.1s, transform 0.6s ease 0.1s",
          }}
        >
          <h1 style={{ fontFamily: FONT_DISPLAY, fontSize: 32, marginBottom: 10, color: COLORS.text }}>
            {product.name}
          </h1>
          <p style={{ fontFamily: FONT_DISPLAY, fontSize: 26, marginBottom: 18, color: COLORS.text }}>
            {money(product.price)}
          </p>

          {product.description && (
            <p style={{ fontSize: 14, lineHeight: 1.6, color: COLORS.textSoft, marginBottom: 28 }}>
              {product.description}
            </p>
          )}
          {product.weightGrams > 0 && (
            <p style={{ fontSize: 12.5, color: COLORS.textFaint, marginBottom: 28, marginTop: -18 }}>
              Weight: {product.weightGrams >= 1000
                ? `${(product.weightGrams / 1000).toFixed(2)} kg`
                : `${product.weightGrams} g`}
            </p>
          )}

          <div
            className="flex items-center"
            style={{
              border: `1px solid ${COLORS.border}`,
              borderRadius: 12,
              width: "fit-content",
              marginBottom: 12,
              overflow: "hidden",
            }}
          >
            <button
              onClick={() => setQty((q) => Math.max(1, q - 1))}
              className="pd-qty-btn"
              style={{ background: "none", border: "none", padding: "10px 14px", color: COLORS.text }}
              aria-label="Decrease quantity"
            >
              <Minus size={14} />
            </button>
            <span style={{ fontSize: 14, minWidth: 24, textAlign: "center" }}>{qty}</span>
            <button
              onClick={() => setQty((q) => Math.min(q + 1, Math.max(1, remaining)))}
              disabled={remaining <= 1}
              className="pd-qty-btn"
              style={{
                background: "none",
                border: "none",
                padding: "10px 14px",
                color: remaining <= 1 ? COLORS.textFaint : COLORS.text,
              }}
              aria-label="Increase quantity"
            >
              <Plus size={14} />
            </button>
          </div>

          {inCartQty > 0 && (
            <p className="pd-in-cart-note" style={{ fontSize: 12.5, color: COLORS.textMuted, marginBottom: 14 }}>
              {inCartQty} already in your bag
            </p>
          )}

          <button
            onClick={handleAdd}
            disabled={outOfStock || remaining <= 0}
            className="pd-add-btn"
            style={{
              width: "100%",
              maxWidth: 320,
              background: outOfStock || remaining <= 0
                ? COLORS.border
                : added
                ? COLORS.verdigris
                : COLORS.surfaceStrong,
              color: outOfStock || remaining <= 0 ? COLORS.textSoft : COLORS.textOnStrong,
              border: "none",
              borderRadius: 14,
              padding: "15px 0",
              fontSize: 14,
              letterSpacing: "0.03em",
              cursor: outOfStock || remaining <= 0 ? "not-allowed" : "pointer",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 8,
            }}
          >
            {added && <Check size={16} className="pd-check" />}
            {outOfStock
              ? "Out of stock"
              : remaining <= 0
              ? "Max stock in bag"
              : added
              ? "Added to bag"
              : "Add to bag"}
          </button>

          <p style={{ fontSize: 11.5, color: COLORS.textFaint, marginTop: 14 }}>
            Shipping and duties calculated at checkout.
          </p>
        </div>
      </div>
    </section>
  );
}
